<?php
declare(strict_types=1);
session_name('openhost_session');
session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>(!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS']!=='off'),'httponly'=>true,'samesite'=>'Strict']);
session_start();
const DATA_DIR='/opt/openhost-panel/data';
const USER_FILE=DATA_DIR.'/admin.json';
const TOKEN_FILE='/etc/openhost-panel/agent.token';
const FILE_MAX_BYTES=1048576;
function e(string $value): string { return htmlspecialchars($value, ENT_QUOTES|ENT_SUBSTITUTE, 'UTF-8'); }
function csrf(): string { if(empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function loadUser(): array { $data=json_decode((string)@file_get_contents(USER_FILE),true); return is_array($data)?$data:['username'=>'admin','hash'=>'','must_change'=>true]; }
function saveUser(array $user): void { $tmp=USER_FILE.'.tmp'; if(file_put_contents($tmp,json_encode($user,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX)===false) throw new RuntimeException('Tidak dapat menyimpan akun.'); chmod($tmp,0600); if(!rename($tmp,USER_FILE)) throw new RuntimeException('Tidak dapat memperbarui akun.'); }
function agentRequest(string $method,string $path,array $payload=[]): array {
  $token=trim((string)@file_get_contents(TOKEN_FILE)); if($token==='') return ['ok'=>false,'error'=>'Token agent tidak dapat dibaca.'];
  $headers="Authorization: Bearer {$token}\r\n"; $content='';
  if($method==='POST') { $content=json_encode($payload,JSON_UNESCAPED_SLASHES); $headers.="Content-Type: application/json\r\n"; }
  $context=stream_context_create(['http'=>['method'=>$method,'timeout'=>45,'ignore_errors'=>true,'header'=>$headers,'content'=>$content]]);
  $body=@file_get_contents('http://127.0.0.1:8787'.$path,false,$context); $data=json_decode((string)$body,true);
  return is_array($data)?$data:['ok'=>false,'error'=>'Agent offline atau memberi respons tidak valid.'];
}
function validDomain(string $domain): bool { return strlen($domain)<=253 && (bool)preg_match('/^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)(?:\.(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?))+$/',strtolower($domain)); }

$user=loadUser(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST') {
  if(!hash_equals((string)($_SESSION['csrf']??''),(string)($_POST['csrf']??''))) { http_response_code(400); $error='Sesi keamanan tidak valid. Muat ulang halaman.'; }
  elseif(isset($_POST['login'])) {
    $candidate=loadUser(); $username=trim((string)($_POST['username']??'')); $password=(string)($_POST['password']??'');
    if($candidate['hash']!=='' && hash_equals((string)$candidate['username'],$username) && password_verify($password,(string)$candidate['hash'])) { session_regenerate_id(true); $_SESSION['user']=$candidate['username']; header('Location: /'); exit; }
    usleep(250000); $error='Username atau password salah.';
  } elseif(isset($_POST['change_password']) && !empty($_SESSION['user'])) {
    $candidate=loadUser(); $new=(string)($_POST['new_password']??''); $confirm=(string)($_POST['confirm_password']??'');
    if(strlen($new)<12) $error='Password baru minimal 12 karakter.';
    elseif($new!==$confirm) $error='Konfirmasi password tidak sama.';
    else { $candidate['hash']=password_hash($new,PASSWORD_DEFAULT); $candidate['must_change']=false; try { saveUser($candidate); session_regenerate_id(true); $_SESSION['csrf']=bin2hex(random_bytes(32)); header('Location: /'); exit; } catch(Throwable $t) { $error=$t->getMessage(); } }
  } elseif(isset($_POST['site_create']) && !empty($_SESSION['user']) && empty($user['must_change'])) {
    $domain=strtolower(trim((string)($_POST['domain']??'')));
    if(!validDomain($domain)) $error='Format domain tidak valid. Contoh: example.com';
    else { $result=agentRequest('POST','/api/v1/sites/create',['domain'=>$domain]); if(!empty($result['ok'])) { $_SESSION['flash']='Website '.$domain.' berhasil dibuat.'; header('Location: /?page=websites'); exit; } $error=(string)($result['error']??'Gagal membuat website.'); }
  } elseif(isset($_POST['site_disable']) && !empty($_SESSION['user']) && empty($user['must_change'])) {
    $domain=strtolower(trim((string)($_POST['domain']??'')));
    if(!validDomain($domain)) $error='Format domain tidak valid.';
    else { $result=agentRequest('POST','/api/v1/sites/disable',['domain'=>$domain]); if(!empty($result['ok'])) { $_SESSION['flash']='Website '.$domain.' dinonaktifkan. File tetap disimpan.'; header('Location: /?page=websites'); exit; } $error=(string)($result['error']??'Gagal menonaktifkan website.'); }
  } elseif(isset($_POST['file_save']) && !empty($_SESSION['user']) && empty($user['must_change'])) {
    $domain=strtolower(trim((string)($_POST['domain']??''))); $path=(string)($_POST['path']??''); $content=(string)($_POST['content']??'');
    if(!validDomain($domain)) $error='Domain tidak valid.';
    elseif(strlen($content)>FILE_MAX_BYTES) $error='File maksimal 1 MiB.';
    else { $result=agentRequest('POST','/api/v1/files/write',['domain'=>$domain,'path'=>$path,'content'=>$content]); if(!empty($result['ok'])) { $_SESSION['flash']='File berhasil disimpan.'; header('Location: /?page=files&domain='.rawurlencode($domain).'&edit='.rawurlencode($path)); exit; } $error=(string)($result['error']??'Gagal menyimpan file.'); }
  } elseif(isset($_POST['file_create']) && !empty($_SESSION['user']) && empty($user['must_change'])) {
    $domain=strtolower(trim((string)($_POST['domain']??''))); $path=trim((string)($_POST['path']??'')); $content=(string)($_POST['content']??'');
    if(!validDomain($domain)) $error='Domain tidak valid.';
    elseif($path==='') $error='Nama file wajib diisi.';
    elseif(strlen($content)>FILE_MAX_BYTES) $error='File maksimal 1 MiB.';
    else { $result=agentRequest('POST','/api/v1/files/create',['domain'=>$domain,'path'=>$path,'content'=>$content]); if(!empty($result['ok'])) { $_SESSION['flash']='File baru berhasil dibuat.'; header('Location: /?page=files&domain='.rawurlencode($domain).'&edit='.rawurlencode($path)); exit; } $error=(string)($result['error']??'Gagal membuat file.'); }
  } elseif(isset($_POST['folder_create']) && !empty($_SESSION['user']) && empty($user['must_change'])) {
    $domain=strtolower(trim((string)($_POST['domain']??''))); $path=trim((string)($_POST['path']??''));
    if(!validDomain($domain)) $error='Domain tidak valid.';
    elseif($path==='') $error='Nama folder wajib diisi.';
    else { $result=agentRequest('POST','/api/v1/files/mkdir',['domain'=>$domain,'path'=>$path]); if(!empty($result['ok'])) { $_SESSION['flash']='Folder berhasil dibuat.'; header('Location: /?page=files&domain='.rawurlencode($domain).'&path='.rawurlencode(dirname($path)==='.'?'':dirname($path))); exit; } $error=(string)($result['error']??'Gagal membuat folder.'); }
  } elseif(isset($_POST['file_delete']) && !empty($_SESSION['user']) && empty($user['must_change'])) {
    $domain=strtolower(trim((string)($_POST['domain']??''))); $path=(string)($_POST['path']??'');
    if(!validDomain($domain)) $error='Domain tidak valid.';
    elseif($path==='') $error='Document root tidak dapat dihapus.';
    else { $result=agentRequest('POST','/api/v1/files/delete',['domain'=>$domain,'path'=>$path]); if(!empty($result['ok'])) { $_SESSION['flash']='Item berhasil dihapus.'; header('Location: /?page=files&domain='.rawurlencode($domain).'&path='.rawurlencode(dirname($path)==='.'?'':dirname($path))); exit; } $error=(string)($result['error']??'Gagal menghapus item.'); }
  } elseif(isset($_POST['ssl_enable']) && !empty($_SESSION['user']) && empty($user['must_change'])) {
    $domain=strtolower(trim((string)($_POST['domain']??''))); $email=trim((string)($_POST['email']??''));
    if(!validDomain($domain)) $error='Domain tidak valid.';
    elseif(!filter_var($email,FILTER_VALIDATE_EMAIL)) $error='Alamat email tidak valid.';
    else { $result=agentRequest('POST','/api/v1/ssl/enable',['domain'=>$domain,'email'=>$email]); if(!empty($result['ok'])) { $_SESSION['flash']='SSL untuk '.$domain.' berhasil diaktifkan.'; header('Location: /?page=ssl'); exit; } $error=(string)($result['error']??'Gagal mengaktifkan SSL.'); }
  } elseif(isset($_POST['database_create']) && !empty($_SESSION['user']) && empty($user['must_change'])) {
    $result=agentRequest('POST','/api/v1/databases/create',['confirm'=>true]);
    if(!empty($result['ok'])) {
      $_SESSION['new_db_credentials']=['database'=>(string)$result['database'],'username'=>(string)$result['username'],'password'=>(string)$result['password']];
      $_SESSION['flash']='Database berhasil dibuat. Salin kredensial di bawah sekarang.';
      header('Location: /?page=databases'); exit;
    }
    $error=(string)($result['error']??'Gagal membuat database.');
  } elseif(isset($_POST['database_backup']) && !empty($_SESSION['user']) && empty($user['must_change'])) {
    $database=(string)($_POST['database']??'');
    if(!preg_match('/^oh_[a-f0-9]{10}$/',$database)) $error='Nama database tidak valid.';
    else { $result=agentRequest('POST','/api/v1/databases/backup',['database'=>$database]); if(!empty($result['ok'])) { $_SESSION['flash']='Backup '.$database.' berhasil dibuat: '.(string)$result['backup']; header('Location: /?page=databases'); exit; } $error=(string)($result['error']??'Backup gagal.'); }
  } elseif(isset($_POST['database_delete']) && !empty($_SESSION['user']) && empty($user['must_change'])) {
    $database=(string)($_POST['database']??''); $confirmation=(string)($_POST['confirmation']??'');
    if(!preg_match('/^oh_[a-f0-9]{10}$/',$database)) $error='Nama database tidak valid.';
    elseif($confirmation!==$database) $error='Ketik nama database secara persis untuk mengonfirmasi.';
    else { $result=agentRequest('POST','/api/v1/databases/delete',['database'=>$database,'confirmation'=>$confirmation]); if(!empty($result['ok'])) { $_SESSION['flash']='Database '.$database.' dan akun khususnya dihapus.'; header('Location: /?page=databases'); exit; } $error=(string)($result['error']??'Gagal menghapus database.'); }
  } elseif(isset($_POST['logout'])) { $_SESSION=[]; session_regenerate_id(true); header('Location: /'); exit; }
}
$logged=!empty($_SESSION['user']); $user=loadUser(); $page=(string)($_GET['page']??'dashboard');
$metrics=agentRequest('GET','/api/v1/metrics');
